# Let me try various special row transformations
test_input = [
    [4, 9, 9, 6],
    [4, 4, 4, 6],
    [4, 4, 6, 4],
    [1, 2, 5, 1],
    [4, 2, 4, 2],
    [4, 4, 4, 4],
    [2, 4, 4, 6]
]

# Variant A: 1→4, 5→2
output_a = []
for row in test_input:
    new_row = []
    for cell in row:
        if cell == 1: new_row.append(4)
        elif cell == 5: new_row.append(2)
        elif cell == 9: new_row.append(6)
        else: new_row.append(cell)
    output_a.append(new_row)

print("Variant A (1->4, 5->2, 9->6):")
for row in output_a:
    print(row)

# Variant B: 1→4, 5→6
output_b = []
for row in test_input:
    new_row = []
    for cell in row:
        if cell == 1: new_row.append(4)
        elif cell == 5: new_row.append(6)
        elif cell == 9: new_row.append(6)
        else: new_row.append(cell)
    output_b.append(new_row)

print("\nVariant B (1->4, 5->6, 9->6):")
for row in output_b:
    print(row)

# Variant C: 1→4, 5→4, 9→6
output_c = []
for row in test_input:
    new_row = []
    for cell in row:
        if cell == 1: new_row.append(4)
        elif cell == 5: new_row.append(4)
        elif cell == 9: new_row.append(6)
        else: new_row.append(cell)
    output_c.append(new_row)

print("\nVariant C (1->4, 5->4, 9->6):")
for row in output_c:
    print(row)

